CREATE TABLE AMULETS (
  AMULET_ID INTEGER NOT NULL PRIMARY KEY,
  BURIAL_ID INTEGER NOT NULL,
  SITE_ID INTEGER NOT NULL,
  TYPE VARCHAR(45) NOT NULL,
  FORM VARCHAR(45) NOT NULL,
  FORM2 VARCHAR(45),
  FORM3 VARCHAR(45),
  MATERIAL VARCHAR(45),
  COLOUR VARCHAR(45),
  LOCATION VARCHAR(45),
  ADORNMENT BOOLEAN NOT NULL,
  PLAQUE BOOLEAN NOT NULL,
  AEGIS BOOLEAN NOT NULL,
  BEAD BOOLEAN NOT NULL,
  DESCRIPTION VARCHAR(200),
  INSCRIBED BOOLEAN NOT NULL,
  MUSEUM VARCHAR(100),
  REF VARCHAR(100),
  CONSTRAINT FK_AMULETS_SITE FOREIGN KEY (SITE_ID) REFERENCES SITES,
  CONSTRAINT FK_AMULETS_BURIAL FOREIGN KEY (BURIAL_ID) REFERENCES BURIALS
);
